#define main legacy_main
#include "minkowski-cuda/main.cu"
#undef main
#include <vector>
int main(){constexpr int mm=64,nn=128,kk=128;int repeat=10;std::vector<float>a(mm*nn),b(nn*kk),out(mm*kk),want(mm*kk),values;for(int i=0;i<mm*nn;i++)a[i]=float(i%31-15)/128.f;for(int i=0;i<nn*kk;i++)b[i]=float(i%17+1)/256.f;float *da,*db,*dc;cudaMalloc(&da,a.size()*4);cudaMalloc(&db,b.size()*4);cudaMalloc(&dc,out.size()*4);cudaMemcpy(da,a.data(),a.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(db,b.data(),b.size()*4,cudaMemcpyHostToDevice);for(int p=1;p<=4;p++)minkowski<mm,nn,kk><<<dim3(kk/16,mm/16),dim3(16,16)>>>(da,db,dc,float(p),1.f/p);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;
for(int trial=1;trial<=5;trial++){values.clear();double times[4],total=0.,err=0.;bool correct=true;for(int p=1;p<=4;p++){cudaMemset(dc,0,out.size()*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)minkowski<mm,nn,kk><<<dim3(kk/16,mm/16),dim3(16,16)>>>(da,db,dc,float(p),1.f/p);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;times[p-1]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;total+=times[p-1];cudaMemcpy(out.data(),dc,out.size()*4,cudaMemcpyDeviceToHost);for(int row=0;row<mm;row++)for(int col=0;col<kk;col++){float s=0.;for(int j=0;j<nn;j++)s+=powf(fabsf(a[row*nn+j]-b[j*kk+col]),float(p));float target=powf(s,1.f/p);float got=out[row*kk+col];err=fmax(err,fabs(double(got)-target));correct &=std::isfinite(got)&&fabsf(got-target)<=1e-5f;}values.insert(values.end(),out.begin(),out.end());}char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(values.data(),4,values.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.14g,\"timing_region\":\"sum_four_p_synchronized_kernel_loop_means\",\"jit_excluded\":true,\"internal_repeats\":%d,\"subkernel_times_seconds\":[%.14g,%.14g,%.14g,%.14g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,correct?"true":"false",values.size(),err,repeat,times[0],times[1],times[2],times[3],file,values.size());if(!correct)return 1;}cudaFree(da);cudaFree(db);cudaFree(dc);}
